#include "idle_dim_policy.h"

#include <assert.h>

int main(void)
{
    assert(idle_dim_brightness(0, 0, true) == 180);
    assert(idle_dim_brightness(59999, 0, true) == 180);
    assert(idle_dim_brightness(60000, 0, true) == 22);
    assert(idle_dim_brightness(70000, 0, false) == 0);
    assert(idle_dim_brightness(10, 20, true) == 0);
    return 0;
}

#include "idle_dim_policy.h"

uint8_t idle_dim_brightness(uint64_t now_ms, uint64_t last_interaction_ms, bool display_active)
{
    if (!display_active || now_ms < last_interaction_ms) return 0;
    return now_ms - last_interaction_ms >= 60000u ? 22u : 180u;
}

